class ShoppingCart {
    constructor() {
        this.items = JSON.parse(localStorage.getItem('cart')) || [];
        this.updateCartCount();
    }

    addItem(productId, name, price) {
        const item = this.items.find(i => i.id === productId);
        if (item) {
            item.quantity += 1;
        } else {
            this.items.push({ id: productId, name, price, quantity: 1 });
        }
        this.save();
        this.updateCartCount();
        this.showToast(`${name} added to cart`);
    }

    save() {
        localStorage.setItem('cart', JSON.stringify(this.items));
    }

    updateCartCount() {
        const total = this.items.reduce((sum, item) => sum + item.quantity, 0);
        document.querySelector('.cart-count').textContent = total;
    }

    showToast(message) {
        const toast = document.getElementById('toast');
        toast.textContent = message;
        toast.classList.add('show');
        setTimeout(() => toast.classList.remove('show'), 2000);
    }
}

// Initialize cart
const cart = new ShoppingCart();

// Add to cart button handlers
document.querySelectorAll('.add-to-cart').forEach(button => {
    button.addEventListener('click', function() {
        const productId = this.getAttribute('data-product');
        const productCard = this.closest('.product-card');
        const productName = productCard.querySelector('.product-info h3').textContent;
        const priceText = productCard.querySelector('.price').textContent;
        const price = parseFloat(priceText.replace(/[$,]/g, '').split(' ')[0]);

        cart.addItem(productId, productName, price);
    });
});

// Smooth scroll for navigation links
document.querySelectorAll('a[href^="#"]').forEach(anchor => {
    anchor.addEventListener('click', function(e) {
        const href = this.getAttribute('href');
        if (href !== '#' && document.querySelector(href)) {
            e.preventDefault();
            document.querySelector(href).scrollIntoView({
                behavior: 'smooth',
                block: 'start'
            });
        }
    });
});

// Newsletter form submission
const newsletterForm = document.querySelector('.newsletter-form');
newsletterForm.addEventListener('submit', function(e) {
    e.preventDefault();
    const email = this.querySelector('input[type="email"]').value;
    cart.showToast(`Subscribed with ${email}`);
    this.reset();
});

// CTA Button
const ctaButton = document.querySelector('.cta-button');
ctaButton.addEventListener('click', function() {
    const featuredSection = document.querySelector('#featured');
    featuredSection.scrollIntoView({ behavior: 'smooth' });
});

// Deal button handlers
document.querySelectorAll('.deal-button').forEach(button => {
    button.addEventListener('click', function() {
        const dealTag = this.parentElement.querySelector('.deal-tag').textContent;
        cart.showToast(`${dealTag} - Redirecting to deals...`);
    });
});

// Product card animations on scroll
const observerOptions = {
    threshold: 0.1,
    rootMargin: '0px 0px -50px 0px'
};

const observer = new IntersectionObserver(function(entries) {
    entries.forEach(entry => {
        if (entry.isIntersecting) {
            entry.target.style.opacity = '1';
            entry.target.style.transform = 'translateY(0)';
        }
    });
}, observerOptions);

document.querySelectorAll('.product-card, .deal-card, .editorial-card').forEach(card => {
    card.style.opacity = '0';
    card.style.transform = 'translateY(20px)';
    card.style.transition = 'opacity 0.6s ease, transform 0.6s ease';
    observer.observe(card);
});

// Hover effects on product cards
document.querySelectorAll('.product-card').forEach(card => {
    card.addEventListener('mouseenter', function() {
        this.style.transform = 'translateY(-8px)';
    });
    card.addEventListener('mouseleave', function() {
        this.style.transform = 'translateY(0)';
    });
});

// Read more article links
document.querySelectorAll('.read-more').forEach(link => {
    link.addEventListener('click', function(e) {
        e.preventDefault();
        const title = this.parentElement.querySelector('h3').textContent;
        cart.showToast(`Reading: ${title}`);
    });
});

// Navigation scroll effect
const navbar = document.querySelector('.navbar');
let lastScrollY = 0;

window.addEventListener('scroll', () => {
    const currentScrollY = window.scrollY;

    if (currentScrollY > 100) {
        navbar.style.boxShadow = '0 4px 12px rgba(0, 0, 0, 0.3)';
    } else {
        navbar.style.boxShadow = 'none';
    }

    lastScrollY = currentScrollY;
});

// Join membership button
document.querySelectorAll('.deal-button').forEach(button => {
    if (button.textContent === 'Join') {
        button.addEventListener('click', function() {
            cart.showToast('Join our membership for exclusive benefits!');
        });
    }
});

// Keyboard navigation support
document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') {
        const toast = document.getElementById('toast');
        toast.classList.remove('show');
    }
});

// Accessibility: ensure proper focus states
document.querySelectorAll('button, a').forEach(element => {
    element.addEventListener('focus', function() {
        this.style.outline = `2px solid var(--accent-gold)`;
        this.style.outlineOffset = '2px';
    });

    element.addEventListener('blur', function() {
        this.style.outline = 'none';
    });
});
