    flex-wrap: wrap;
    gap: 2rem;
}

.footer-bottom p {
    color: var(--text-tertiary);
    font-size: 0.9rem;
}

.social-links {
    display: flex;
    gap: 1.5rem;
}

.social-links a {
    color: var(--text-secondary);
    font-weight: 600;
    font-size: 0.95rem;
}

.social-links a:hover {
    color: var(--accent-gold);
}

/* Toast Notification */
.toast {
    position: fixed;
    bottom: 2rem;
    right: 2rem;
    background-color: var(--accent-gold);
    color: var(--bg-primary);
    padding: 1rem 1.5rem;
    border-radius: 4px;
    font-weight: 600;
    opacity: 0;
    pointer-events: none;
    transition: opacity 0.3s ease;
    z-index: 2000;
}

.toast.show {
    opacity: 1;
    pointer-events: auto;
}

/* Responsive Design */
@media (max-width: 768px) {
    .hero {
        grid-template-columns: 1fr;
        padding: 3rem 0;
        min-height: auto;
    }

    .hero-content h1 {
        font-size: 2rem;
    }

    .hero-content p {
        font-size: 1rem;
    }

    .section-title {
        font-size: 1.8rem;
        margin-bottom: 2rem;
    }

    .products-grid {
        grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
        gap: 1.5rem;
    }

    .deals-grid {
        grid-template-columns: 1fr;
    }

    .deal-card.large {
        min-height: 250px;
    }

    .editorial-grid {
        grid-template-columns: 1fr;
    }

    .editorial-card.featured-article {
        grid-row: span 1;
    }

    .editorial-card.featured-article .article-image {
        height: 250px;
    }

    .newsletter-container {
        flex-direction: column;
    }

    .newsletter-form {
        flex-direction: column;
        max-width: none;
    }

    .newsletter-form button {
        width: 100%;
    }

    .footer-grid {
        grid-template-columns: repeat(2, 1fr);
    }

    .footer-bottom {
        flex-direction: column;
    }

    .nav-links {
        gap: 1rem;
        font-size: 0.85rem;
    }
}

@media (max-width: 480px) {
    .container {
        padding: 0 15px;
    }

    .hero {
        padding: 2rem 0;
    }

    .hero-content h1 {
        font-size: 1.5rem;
    }

    .section-title {
        font-size: 1.4rem;
        margin-bottom: 1.5rem;
    }

    .products-grid {
        grid-template-columns: 1fr;
    }

    .nav-links {
        gap: 0.75rem;
